def is_cool(seq):
    n = len(seq)
    for i in range(1, n):
        if sum(seq[1:i+1]) != seq[0] or sum(seq[i+1:]) != seq[i]:
            return False
    return True

def min_cool_transitions(n, seq):
    dp = [float('inf')] * n
    for i in range(n - 1, -1, -1):
        smallest_possible = 1
        for j in range(i + 1, n):
            s = sum(seq[i:j])
            if is_cool(seq[i:j]):
                smallest_possible = j
            dp[i] = min(dp[i], j - i - s + smallest_possible)
    return min(dp)

