def kmp_search(pattern, text):
    M, N = len(pattern), len(text)
    lps = [0] * M
    j = 0  # length of the previous longest prefix suffix

    # Precompute the look ahead table
    length = 0
    for i in range(1, M):
        while j and pattern[i] != pattern[j]:
            j = lps[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
        if j == M:
            lps[i] = M
        else:
            lps[i] = lps[j]

    i = 0  # index for text[]
    results = set()
    j = 0  # index for pattern[]

    while i < N:
        if j == M:
            results.add(text[0:M])
            i += M
        elif pattern[j] == text[i]:
            j += 1
            (i, j) = (i + 1, j)
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return results

def monotone_triples_free(L, R, sequence):
    """
    This method finds numerically in ordered sequence, size greater than 2, that doesn't contain any monotone triples
    """
    for k in range(L, R + 1):
        found = True
        seen = set()  # to see if search can be finished more efficiently
        start = 0
        end = k

        while start < len(sequence):
            if end == len(sequence):
