from typing import List

class ModularXorTree:
    def __init__(self, n: int):
        self.size = 1 << n.bit_length()
        self.tree = [0] * self.size
        self.modulus = 10**9 + 7

    def query(self, left: int, right: int) -> int:
        left -= 1
        right -= 1
        x = 0
        for i in range(n-1, -1, -1):
            if left & (1 << i):
                x ^= self.tree[self.size - left - 1]
            left |= (1 << i)
            if right & (1 << i):
                x ^= self.tree[right]
            right -= 1 << i
        return (x % self.modulus + self.modulus) % self.modulus

    def update(self, index: int, value: int, flush_updates: bool) -> None:
        index += 1
        value = value % self.modulus
        for i in range(n-1, -1, -1):
            left = index & (1 << i)
            if left:
                if index & (1 << (i+1)):
                    value ^= self.tree[2 * index]
                self.tree[index] = value
            if index | (1 << (i+1)):
                if not index & (1 << (i+1)):
                    value ^= self.tree[index + self.size // (1 << i)]
                self.tree[index] = value
            index >>= i

def solve_queries(queries: List[List[int]]) -> List[int]:
    mod_tree = ModularXorTree(30)
    last_updated_index = 0
    for query in queries:
        t, l, r = query
        if t == 1:
            mod_tree.update(l, r & r ^ l, True)
            if r > l:
                mod_tree.update(r + 1, l & l ^ r, True)
            last_updated_index = r + 1
        elif t == 2:
            l, r = l + 1, r + 1
            if l <= last_updated_index and mod_tree.query(l - 1, r - 1) == last_updated_index:
                # Check if it's still impossible to know the xor value
                x = mod_tree.modulus - 1 if last_updated_index != mod_tree.modulus - 1 else 0
                return [x] if x < mod_tree.modulus else [-1]
            else:
                last_updated_index = l - 1
                return [mod_tree.query(l - 1, r - 1)]
    return [0] * len(queries)
