def max_journey_length(n: int, s: str) -> int:
    journeys = []
    part_length = 1
    for left in range(n):
        right = left + 1
        current = ""
        while right < n and len(current) < part_length and len(s[right]) < len(s[left]) + 1:
            if s[left] == s[right]:
                current += s[right]
                right += 1
            else:
