def min_sum_of_differences(N, tree, L, A, R):
    dp = {}
    def dfs(node, parent):
        if node in dp:
            return dp[node]
        for child in tree[node]:
            if child != parent:
                val_left = max(dfs(child, node) for _ in range(L[node] - 1, A[node]))
                val_right = min(dfs(child, node) for _ in range(A[node], R[node]))
                dp[node] += (val_left + val_right)
        return dp[node]
    dfs(0, None)
    return sum(dp[i] for i in range(1, N)) + sum(dfs(0, None) for _ in range(N))
