import sys

def dfs(class_tree, target, current_level, already_visited, level):
    if current_level in already_visited:
        return already_visited[current_level]
    elif class_tree[current_level] == target:
        already_visited[current_level] = level
        return level
    else:
        maximum_cost = 0
        class_cost = 0
        potential_class = sys.maxsize
        for child in class_tree[current_level]:
            child_path_cost = dfs(class_tree, target, child, already_visited, level + 1)
            if class_cost == 0:
                class_cost = child_path_cost
            else:
                class_cost = min(class_cost, child_path_cost)
            if class_cost >= child_path_cost:
                if potential_class > child_path_cost:
                    potential_class = child_path_cost
        if potential_class == 0:
            already_visited[current_level] = level
            return level
        elif potential_class > level:
            already_visited[current_level] = level + 1
            return level + 1
        else:
            already_visited[current_level] = level + max(class_cost, potential_class)
            return level + max(class_cost, potential_class)
    return -1  # This should not happen

def find_classes_in_level(class_tree, level, target, length):
    already_visited = {}
    total_classes = dfs(class_tree, target, 1, already_visited, -1)
    matching_classes = 0
    for i in range(1, length):
        current_cost = length - dfs(class_tree, target, i, already_visited, -1)
        matching_classes += length - i >= current_cost and already_visited[i] >= length - (1 + length - current_cost)
    return matching_classes

