import sys

def is_possible(n, friends):
    if n % 2 == 0:
        return False
    pairs = n // 2
    odd_cants = 0
    for friend in friends:
        if friendly[friend] == 1:
            even_ids = True
            while friend > 1 and not even_ids:
                if friendly[friend] == 1:
                    even_ids = False
                friend //= 2
            odd_ids = True
            while friend < n and not odd_ids:
                if friendly[friend] == 1:
                    odd_ids = False
                friend += n
            if odd_ids and even_ids:
                odd_cants += 1
    return n // 2 <= odd_cants <= pairs

def solve(test_cases):
    for i in range(1, test_cases + 1):
        n, m = map(int, input().split())
        friendly = [0] * (n + 1)
        num_friends = [0] * (n + 1)
        for j in range(m):
            friend, cat = map(int, input().split())
            friendly[cat] = 1
            if cat > 1:
                num_friends[cat] += 1
            else:
                num_friends[cat] -= 1
