            j = 1
            c = set()
            for cat in range(1, n + 1):
                if num_friends[cat] == 0:
                    j += 1
                    c.add(cat)
            p = n - j
            print(f"Test #{i}: {j} {p}")
            print(f"Test #{i}: {sorted(list(c))}")
            print(f"Test #{i}: {sorted(list(range(1, n+1))) + sorted(list(c))}")

