    # Calculate lines for Victor and Peter
    x_para_v = (xp - xv) * (yw1 + yw2) - (ym1 + ym2) * (yp - yv)
    y_para_v = (xp - xv) * (ym2 - ym1) + (yp - yv) * (xm2 - xm1 - (xm2 - xm1) * (xm1 - xw1 + xw1 - xw2)/(yw1 + yw2))

    # Apply mirror-line reflection symmetry
    x_para_mirror = 2 * xw1 - xpara_v
    y_para_mirror = 2 * yw1 - ypara_v

    # Calculate mirror angle with xv-yv vector
    if abs(xpara_v + ypara_v) > 1e-6:
        return False

    # See if reflection angle makes the mirror line parallel to the line of sight
    if abs(xw1 - xpara_mirror) == 0.0:  # parallel
        return False

    # Does the mirror line intersect the line of sight?
    if xp == xv:
        if abs(yp - yv) < abs(yw1 + yw2) or abs(yp - yv) < abs(ym1 + ym2):
