def calculate_xor_subarray(X):
    xor_value = X[0]
    for i in range(1, X.size):
        XOR_1 = xor_value ^ X[i]
        if XOR_1 > X[-1] / 2:
            skip = True
            for j in range(len(X)):
                if X[j] == X[-1] / 2:
                    skip = False
                    break
            while skip:
                XOR_1 >>= 1
                if XOR_1 < X[0] / 2:
                    break
                if XOR_1 > X[-1] / 2:
                    skip = False
                    continue
                for j in range(len(X)):
                    if XOR_1 == X[j]:
                        xor_value = X[0] ^ XOR_1
                        return xor_value
    return np.inf

