from heapq import heappop, heappush
from collections import defaultdict

class Graph:
    def __init__(self, n):
        self.graph = defaultdict(list)
        self.ranking = 0
        self.index = {}
        self.max_cost = {}
        self.back = defaultdict(list)
        self.n = n

    def add_edge(self, u, v):
        self.graph[u].append(v)

    def neighbors(self, u, level):
        return self.graph[u][(level+1):]

    def find_parent(self, u):
        if u not in self.index:
            self.index[u] = u
        # If parent is not found
        while u != self.index[u]:
            u = self.index[u]
        return u

    def path_cost(self, u, v, level):
        return self.ranking + self.max_cost[u] + self.max_cost[v] - 2 * self.max_cost[self.find_parent(v)]

    def search_levels(self, level):
        if level == self.n:
            return 1
        connected = set()
        for v in self.neighbors(level, level-1):
            connected.add(self.find_parent(v))
        for v in connected:
            for w in self.neighbors(level, level):
                # heapq.heappush creates min heap, so we lower the cost of the new path
                for wc, v2 in self.neighbors(self.find_parent(v), level):
                    if wc > self.ranking and v == v2:
                        break
                    self.ranking += 1
                    self.back[v].append(v2)
                    self.max_cost[v2] = self.max_cost[v] + level
                    heappush(connections, (self.ranking, v2))

        return sum(len(self.back[n]) == 1 and self.max_cost[n] == level for n in connected)        
