import math

class BitOperations:
    def __init__(self):
        self.bits = [0] * (2**30)

    def update(self, l, r, x):
        for i in range(30, -1, -1):
            mask = 1 << i
            v = x >> i & 1
            l_ = (l & ~(mask - 1)) | (l & mask)^(1 << i)
            r_ = (r & ~(mask - 1)) | (r & mask)^(1 << i)
            if self.bits[l_] == x:
                self.bits[r_] ^= v
            else:
                return False
        return True

    def query(self, l, r):
        for i in range(30, -1, -1):
            mask = 1 << i
            l_ = (l & ~(mask - 1)) | (l & mask)^(1 << i)
            r_ = (r & ~(mask - 1)) | (r & mask)^(1 << i)
            if self.bits[r_] ^ (mask & self.bits[l_]) == 0:
                return l_ ^ r_ ^ 1
        return -1 if self.bits[0] else -1

