import sys

def get_ancestors(graph, root, name):
    count = 0
    visited = [False] * len(graph)
    path = []
    stack = [name]

    def dfs(node):
        nonlocal count, visited, path
        if visited[node]:
            return
        visited[node] = True
        count += 1
        path.append(node)
        for neighbor in graph[node]:
            if neighbor == root:
                return
            dfs(neighbor)

    dfs(root)
    reverse_path = path[::-1]
    for i, name in enumerate(visited):
        if name and name != root:
            dfs(reverse_path[i])
    return count

def solve(person):
