import heapq

def min_steps_to_cast_cards(n, spells):
    def calculate_score(start, end):
        if not spells[start] or not spells[end]:
            return float('inf')
        i, j = spells[start], spells[end]
        ix, iy = max(0, i - 1), min(x, i)
        jx, jy = max(0, j - 1), min(y, j)
        score = (jy - iy) * (jx - ix) + ((jy + jx) // 2 - (i - 1)) * min(abs(jy - i), abs(jx - i))
        return score

    x, y = -1, -1
    for i, j in spells:
        if x < i and x < j:
            x, y = i, j

    d = defaultdict(lambda: float('inf'))
    d[0] = 0
    pq = [(-calculate_score(), 0)]  # We flip negation in priority queue for min-heap
    best_score = float('inf')
    while pq:
        s, i = heapq.heappop(pq)
        if d[i] < s:
            continue
        for j in range(i, min(n, len(spells))):
            nx, ny = -x, -y
            if i == j:
                continue
            if spells[j] == spells[i]:
                score = calculate_score(i, j)
                s += score
                d[j] = s
            elif nx < max(x, spells[j][0]) and ny > min(y, spells[j][1]):
                score = calculate_score(i, j)
                s += score
                d[j] = s
            else:
                continue
            heappush(pq, (-(d[i] + s), j))

    min_moves = -d[n-1] if d[n-1] > 0 else float('inf')
    if min_moves > 1e10:
        print(-1)
    else:
        print(min_moves)
        print([spells[i][1] + 1 for i in range(n) if d[i] == min_moves])

