    opposite_angles = [area((x1, y1, x2, y2), (x2, y2, x3, y3)), area((x2, y2, x3, y3), (x3, y3, x1, y1)), area((x3, y3, x1, y1), (x1, y1, x2, y2))]
    if opposite_angles[2] < 0:
        opposite_angles[2] = 0
    if opposite_angles[0] * opposite_angles[2] <= 0:
        return False

    # Check if the resulting points form a convex shape by making sure two pairs of opposite points have the same area in absolute terms
