        edges = {start_index: []}
        for other_index in unvisited:
            edges[other_index] = set()
            for neighbor_index in candidates:
                if all(candidate != neighbor for neighbor in candidates):
                    edges[other_index].add(other_index)
            for neighbor in candidates - {other_index, candidates[start_index]}:
                if neighbor not in candidates[other_index] or edges[other_index]:
                    edges[other_index].add(edges[other_index])
        cycle = None
        visited = {start_index}
        stack = [start_index]
