import sys

def find_set(parent, x):
    if parent[x] != x:
        return find_set(parent, parent[x])
    return x

def union_set(parent, rank, x, y):
    rootX = find_set(parent, x)
    rootY = find_set(parent, y)
    if rootX != rootY:
        if rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        elif rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def minimum_sum_of_distance(graph):
    n = len(graph)
    parent = list(range(n))
    rank = [0] * n

    for x in range(n):
        for y in graph[x]:
            union_set(parent, rank, x, y)

    distMap = dict()
    for x in parent:
        mapping = {v: d for d, v in enumerate(find_set(parent, x))}
        for y in mapping:
            if y not in distMap:
                distMap[y] = abs(mapping[y] - x)
            else:
                distMap[y] = min(distMap[y], abs(mapping[y] - x))

    return sum(val for val in distMap.values())

